<?php require 'config/database.php';require 'includes/auth.php';require_role('admin');$rows=$pdo->query("SELECT s.*,u.name,m.name AS material FROM recycling_sessions s JOIN users u ON u.id=s.user_id JOIN material_categories m ON m.id=s.material_id WHERE s.status='flagged' ORDER BY s.created_at DESC")->fetchAll();$pageTitle='Submission review';include 'includes/header.php';?><div class="page-heading"><span class="eyebrow">ADMINISTRATION</span><h1>Flagged submissions</h1><p>Weight readings outside expected ranges require manual review. Do not credit points based on material selection alone.</p></div><section class="panel"><?php if(!$rows):?><div class="empty-state">There are no flagged submissions.</div><?php else:foreach($rows as $s):?><div class="claim-row"><div><b><?=htmlspecialchars($s['material'])?> · <?=htmlspecialchars($s['name'])?></b><small>Session #<?=$s['id']?> · <?=htmlspecialchars($s['created_at'])?> · Weight: <?=htmlspecialchars($s['weight_grams']??'Not recorded')?> g</small></div><span class="status flagged">flagged</span></div><?php endforeach;endif;?></section><?php include 'includes/footer.php';?>
